      (n ? '<a class="gv-pg next" href="' + gh(n.id) + '"><small>Next unit →</small><b>' + n.num + ' · ' + n.word + '</b></a>' : '<a class="gv-pg next" href="#lens-water"><small>Next →</small><b>Tier 2 · Water</b></a>') + '</nav>';
